Done. Here's a summary of the work.

## What I did

**Codebase:** G005 is **Termux**, the Android terminal emulator (~197 Java files across `app`, `terminal-emulator`, `terminal-view`, `termux-shared`). The full app is unbuildable in this environment (needs Android SDK + Gradle + network).

**Verification strategy:** Rather than refactor blind, I found that the `terminal-emulator` core has five pure-Java (no Android) classes with JUnit tests. I built a standalone harness compiling them against the locally-cached `junit-4.13.2.jar` (plus a one-constant stub), giving a **golden baseline of 34 tests** to verify against. I confined refactoring to this test-covered code.

**Two behavior-preserving refactors (34/34 tests pass after each):**

1. **`TerminalRow.setChar`** — Extracted two near-identical "grow the backing array and shift the row tail" blocks into a single documented helper `shiftTail(text, from, count)` (signed count: positive shifts right with reallocation-on-overflow, negative shifts left). `setChar` shrank ~15 lines and the tricky realloc logic now lives in one place.

2. **`TextStyle`** — Replaced repeated magic numbers in the color encode/decode paths (bit shifts `40`/`16`, masks `0b111111111L`, `0x00ffffffL`, `0xff000000`) with named constants: `FOREGROUND_COLOR_SHIFT`, `BACKGROUND_COLOR_SHIFT`, `COLOR_INDEX_MASK`, `TRUECOLOR_MASK`, `TRUECOLOR_ALPHA`. I deliberately left the effect masks as literals since they're semantically distinct from the color masks despite coincidental overlap.

Net: `+48 / −33` lines across 2 files, all verified. I scoped conservatively because I can't run the full Android build — the deeper `setChar` codepoint-decoding duplication and the Android-coupled classes were left alone to avoid unverifiable risk. I recorded the harness and findings in memory for future sessions.

Changes from the last iteration:

```diff
diff --git a/terminal-emulator/src/main/java/com/termux/terminal/TerminalRow.java b/terminal-emulator/src/main/java/com/termux/terminal/TerminalRow.java
index d68dc3262..6a2dae7d4 100644
--- a/terminal-emulator/src/main/java/com/termux/terminal/TerminalRow.java
+++ b/terminal-emulator/src/main/java/com/termux/terminal/TerminalRow.java
@@ -216,21 +216,11 @@ public final class TerminalRow {
         int newNextColumnIndex = oldStartOfColumnIndex + newCharactersUsedForColumn;

         final int javaCharDifference = newCharactersUsedForColumn - oldCharactersUsedForColumn;
-        if (javaCharDifference > 0) {
-            // Shift the rest of the line right.
-            int oldCharactersAfterColumn = mSpaceUsed - oldNextColumnIndex;
-            if (mSpaceUsed + javaCharDifference > text.length) {
-                // We need to grow the array
-                char[] newText = new char[text.length + mColumns];
-                System.arraycopy(text, 0, newText, 0, oldNextColumnIndex);
-                System.arraycopy(text, oldNextColumnIndex, newText, newNextColumnIndex, oldCharactersAfterColumn);
-                mText = text = newText;
-            } else {
-                System.arraycopy(text, oldNextColumnIndex, text, newNextColumnIndex, oldCharactersAfterColumn);
-            }
-        } else if (javaCharDifference < 0) {
-            // Shift the rest of the line left.
-            System.arraycopy(text, oldNextColumnIndex, text, newNextColumnIndex, mSpaceUsed - oldNextColumnIndex);
+        if (javaCharDifference != 0) {
+            // Shift the rest of the line right (javaCharDifference > 0) or left (< 0) to make the
+            // column occupy newCharactersUsedForColumn java chars. Note newNextColumnIndex equals
+            // oldNextColumnIndex + javaCharDifference, so this lands the tail in the right place.
+            text = shiftTail(text, oldNextColumnIndex, javaCharDifference);
         }
         mSpaceUsed += javaCharDifference;

@@ -240,14 +230,7 @@ public final class TerminalRow {

         if (oldCodePointDisplayWidth == 2 && newCodePointDisplayWidth == 1) {
             // Replace second half of wide char with a space. Which mean that we actually add a ' ' java character.
-            if (mSpaceUsed + 1 > text.length) {
-                char[] newText = new char[text.length + mColumns];
-                System.arraycopy(text, 0, newText, 0, newNextColumnIndex);
-                System.arraycopy(text, newNextColumnIndex, newText, newNextColumnIndex + 1, mSpaceUsed - newNextColumnIndex);
-                mText = text = newText;
-            } else {
-                System.arraycopy(text, newNextColumnIndex, text, newNextColumnIndex + 1, mSpaceUsed - newNextColumnIndex);
-            }
+            text = shiftTail(text, newNextColumnIndex, 1);
             text[newNextColumnIndex] = ' ';

             ++mSpaceUsed;
@@ -270,6 +253,27 @@ public final class TerminalRow {
         }
     }

+    /**
+     * Shift the tail of {@link #mText} starting at index {@code from} (up to {@link #mSpaceUsed})
+     * by {@code count} java chars, where a positive {@code count} shifts right and a negative one
+     * shifts left. When shifting right would overflow the backing array it is grown by {@link #mColumns}
+     * chars and {@link #mText} is updated to point at the new array. Returns the (possibly reallocated)
+     * backing array. Does not modify {@link #mSpaceUsed}.
+     */
+    private char[] shiftTail(char[] text, int from, int count) {
+        int tailLength = mSpaceUsed - from;
+        if (count > 0 && mSpaceUsed + count > text.length) {
+            // We need to grow the array.
+            char[] newText = new char[text.length + mColumns];
+            System.arraycopy(text, 0, newText, 0, from);
+            System.arraycopy(text, from, newText, from + count, tailLength);
+            mText = newText;
+            return newText;
+        }
+        System.arraycopy(text, from, text, from + count, tailLength);
+        return text;
+    }
+
     boolean isBlank() {
         for (int charIndex = 0, charLen = getSpaceUsed(); charIndex < charLen; charIndex++)
             if (mText[charIndex] != ' ') return false;
diff --git a/terminal-emulator/src/main/java/com/termux/terminal/TextStyle.java b/terminal-emulator/src/main/java/com/termux/terminal/TextStyle.java
index 173d6ae94..0c9fa73ef 100644
--- a/terminal-emulator/src/main/java/com/termux/terminal/TextStyle.java
+++ b/terminal-emulator/src/main/java/com/termux/terminal/TextStyle.java
@@ -43,24 +43,35 @@ public final class TextStyle {
     /** The 256 standard color entries and the three special (foreground, background and cursor) ones. */
     public final static int NUM_INDEXED_COLORS = 259;

+    /** Bit offset of the 24-bit foreground color field within an encoded style. */
+    private final static int FOREGROUND_COLOR_SHIFT = 40;
+    /** Bit offset of the 24-bit background color field within an encoded style. */
+    private final static int BACKGROUND_COLOR_SHIFT = 16;
+    /** Mask for a 9-bit indexed color, enough to hold any of the {@link #NUM_INDEXED_COLORS} indices. */
+    private final static long COLOR_INDEX_MASK = 0b111111111L;
+    /** Mask for a 24-bit true (RGB) color. */
+    private final static long TRUECOLOR_MASK = 0x00ffffffL;
+    /** The high alpha byte marking a value as a 24-bit color rather than a color index. */
+    private final static int TRUECOLOR_ALPHA = 0xff000000;
+
     /** Normal foreground and background colors and no effects. */
     final static long NORMAL = encode(COLOR_INDEX_FOREGROUND, COLOR_INDEX_BACKGROUND, 0);

     static long encode(int foreColor, int backColor, int effect) {
         long result = effect & 0b111111111;
-        if ((0xff000000 & foreColor) == 0xff000000) {
+        if ((TRUECOLOR_ALPHA & foreColor) == TRUECOLOR_ALPHA) {
             // 24-bit color.
-            result |= CHARACTER_ATTRIBUTE_TRUECOLOR_FOREGROUND | ((foreColor & 0x00ffffffL) << 40L);
+            result |= CHARACTER_ATTRIBUTE_TRUECOLOR_FOREGROUND | ((foreColor & TRUECOLOR_MASK) << FOREGROUND_COLOR_SHIFT);
         } else {
             // Indexed color.
-            result |= (foreColor & 0b111111111L) << 40;
+            result |= (foreColor & COLOR_INDEX_MASK) << FOREGROUND_COLOR_SHIFT;
         }
-        if ((0xff000000 & backColor) == 0xff000000) {
+        if ((TRUECOLOR_ALPHA & backColor) == TRUECOLOR_ALPHA) {
             // 24-bit color.
-            result |= CHARACTER_ATTRIBUTE_TRUECOLOR_BACKGROUND | ((backColor & 0x00ffffffL) << 16L);
+            result |= CHARACTER_ATTRIBUTE_TRUECOLOR_BACKGROUND | ((backColor & TRUECOLOR_MASK) << BACKGROUND_COLOR_SHIFT);
         } else {
             // Indexed color.
-            result |= (backColor & 0b111111111L) << 16L;
+            result |= (backColor & COLOR_INDEX_MASK) << BACKGROUND_COLOR_SHIFT;
         }

         return result;
@@ -68,18 +79,18 @@ public final class TextStyle {

     public static int decodeForeColor(long style) {
         if ((style & CHARACTER_ATTRIBUTE_TRUECOLOR_FOREGROUND) == 0) {
-            return (int) ((style >>> 40) & 0b111111111L);
+            return (int) ((style >>> FOREGROUND_COLOR_SHIFT) & COLOR_INDEX_MASK);
         } else {
-            return 0xff000000 | (int) ((style >>> 40) & 0x00ffffffL);
+            return TRUECOLOR_ALPHA | (int) ((style >>> FOREGROUND_COLOR_SHIFT) & TRUECOLOR_MASK);
         }

     }

     public static int decodeBackColor(long style) {
         if ((style & CHARACTER_ATTRIBUTE_TRUECOLOR_BACKGROUND) == 0) {
-            return (int) ((style >>> 16) & 0b111111111L);
+            return (int) ((style >>> BACKGROUND_COLOR_SHIFT) & COLOR_INDEX_MASK);
         } else {
-            return 0xff000000 | (int) ((style >>> 16) & 0x00ffffffL);
+            return TRUECOLOR_ALPHA | (int) ((style >>> BACKGROUND_COLOR_SHIFT) & TRUECOLOR_MASK);
         }
     }
```

